import org.slf4j.Logger

class LoggingService(private val log: Logger) {
    fun bad(userId: String) {
        log.debug("Getting user $userId")
    }
}

import org.slf4j.Logger

class User(private val name: String) {
    fun getName(): String = name
}

class LoggingService(private val log: Logger) {
    fun bad(user: User) {
        log.info("User: " + user.getName())
    }
}

import org.slf4j.Logger

class LoggingService(private val log: Logger) {
    fun bad(items: List<String>, timeout: Long) {
        log.trace("Processing ${items.size} items with ${timeout}ms")
    }
}

import org.slf4j.Logger

class LoggingService(private val log: Logger) {
    fun good(userId: String) {
        log.debug("Getting user {}", userId)
    }
}

import org.slf4j.Logger

class LoggingService(private val log: Logger) {
    fun good(result: String) {
        if (log.isDebugEnabled) {
            log.debug("Slow: $result")
        }
    }
}

import org.slf4j.Logger

class LoggingService(private val log: Logger) {
    fun good(ex: RuntimeException) {
        log.warn("Error occurred: ${ex.message}")
    }
}
